+// functionDayOfYear returns the day of the year for the given timestamp.
+func functionDayOfYear(_ FunctionArgs) OpFunc {
+	return func(vals []parser.Value, _ context.Context) (parser.Value, error) {
+		v := vals[0].(Vector)
+		for i, sample := range v {
+			v[i].V = float64(sample.Ts/1000) / 86400 + 1
+		}
+		return v, nil
+	}
+}
